from collections import deque

def distances(graph, start):
    distance = {start: 0}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor not in distance:
                distance[neighbor] = distance[node] + 1
                queue.append(neighbor)
    return distance

assert distances({'A':['B'], 'B':['C'], 'C':['A']}, 'A') == {'A':0, 'B':1, 'C':2}

def ways(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        raise ValueError('nonnegative integer required')
    previous, current = 1, 1
    for _ in range(n):
        previous, current = current, previous + current
    return previous

assert ways(0) == 1
assert ways(4) == 5

exercise.solution:
def ways_one_or_three(n):
    if not isinstance(n, int) or isinstance(n, bool) or n < 0:
        raise ValueError('nonnegative integer required')
    counts = [0] * (n + 1)
    counts[0] = 1
    for i in range(1, n + 1):
        counts[i] = counts[i - 1]
        if i >= 3:
            counts[i] += counts[i - 3]
    return counts[n]

assert [ways_one_or_three(n) for n in range(7)] == [1, 1, 1, 2, 3, 4, 6]
# For four steps: 1+1+1+1, 1+3 and 3+1 are the three sequences.
# O(n) additions and O(n) stored counts; integer sizes grow with n.

