assert all(result[i][1] <= result[i+1][0] for i in range(len(result)-1))
assert schedule([]) == []
for invalid in [(1, 1), (2, 1)]:
    try:
        schedule([(0, 1), invalid])
    except ValueError:
        pass
    else:
        raise AssertionError("nonpositive duration accepted")

